class NegateFieldTests(TestCase):
    @classmethod
    def setUpTestData(cls):
        cls.true = ReservedName.objects.create(name='true', order=1, negate=True)
        cls.false = ReservedName.objects.create(name='false', order=2, negate=False)

    def test_filter(self):
        for value, expected in ((True, self.true), (False, self.false)):
            with self.subTest(value=value):
                self.assertSequenceEqual(
                    ReservedName.objects.filter(negate=value), [expected],
                )
                self.assertSequenceEqual(
                    ReservedName.objects.filter(Q(order__gt=0), negate=value),
                    [expected],
                )

    def test_exclude(self):
        for value, expected in ((True, self.false), (False, self.true)):
            with self.subTest(value=value):
                self.assertSequenceEqual(
                    ReservedName.objects.exclude(negate=value), [expected],
                )
                self.assertSequenceEqual(
                    ReservedName.objects.exclude(Q(order__gt=0), negate=value),
                    [expected],
                )


